#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

cd "$(git rev-parse --show-toplevel)"
# Remembered answers live inside .git so they can never be committed.
ENV_FILE="$(git rev-parse --git-dir)/zh-tw-wizard.env"
# gh would otherwise pick the `upstream` remote; secrets belong on the fork.
export GH_REPO="${GH_REPO:-$(git remote get-url origin | sed -E 's#^(git@github\.com:|https://github\.com/)##; s#\.git$##')}"
REGION="us-central1"
TERMBASE="zh-tw/termbase.csv"
SA_NAME="angkorgit-translate"
TOKEN=""
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

run() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@"; }
stop() { warn "$1"; exit 1; }

# api METHOD PATH [curl args…] calls Cloud Translation v3, saves the body to $TMP/out.json, prints the HTTP status.
api() {
  local method="$1" path="$2"; shift 2
  curl -sS -o "$TMP/out.json" -w '%{http_code}' -X "$method" \
    -H "Authorization: Bearer $TOKEN" -H "x-goog-user-project: $GCP_PROJECT" \
    -H 'Content-Type: application/json; charset=utf-8' "$@" \
    "https://translation.googleapis.com/v3/projects/$GCP_PROJECT/locations/$REGION$path"
}

# wait_for STATUS PATH polls GET PATH until it answers STATUS (up to 5 minutes).
wait_for() {
  local code
  for _ in $(seq 1 60); do
    code=$(api GET "$2")
    if [[ "$code" == "$1" ]]; then printf '\n'; return 0; fi
    printf '.'; sleep 5
  done
  printf '\n'; return 1
}

banner "AngKorGit zh-TW：Google 翻譯設定"

stage "前置檢查"
for tool in gcloud gh jq curl; do
  command -v "$tool" >/dev/null 2>&1 || stop "找不到 $tool，請先安裝後再重跑。"
done
gh auth status >/dev/null 2>&1 || stop "gh 尚未登入，請先執行 gh auth login。"
[[ -f "$TERMBASE" ]] || stop "找不到 $TERMBASE。"
say "工具都已就緒。術語表來源：$TERMBASE（$(wc -l < "$TERMBASE" | tr -d ' ') 條）"
say "GitHub secret 與 variables 會寫到：$GH_REPO"
confirm "這是你的 fork 嗎？" || stop "請用 GH_REPO=owner/name 重新執行。"

stage "Google 帳號"
ACCOUNT=$(gcloud config get-value account 2>/dev/null || true)
say "gcloud 目前登入的帳號：${ACCOUNT:-（尚未登入）}"
note "這個帳號要能建立 GCP 專案並連結計費帳戶。"
note "換帳號會改變這台電腦 gcloud 的使用中帳號；之後可用 gcloud config set account 換回來。"
if [[ -z "$ACCOUNT" ]] || confirm "要改用另一個 Google 帳號登入嗎？"; then
  run gcloud auth login
  ACCOUNT=$(gcloud config get-value account 2>/dev/null || true)
  say "現在使用：$ACCOUNT"
fi
pause

stage "GCP 專案"
say "輸入要使用的專案 ID；不存在的話會新建。"
note "專案 ID 全球唯一，6–30 個字元，只能用小寫英文、數字與連字號。"
ask GCP_PROJECT "專案 ID："
[[ -n "$GCP_PROJECT" ]] || stop "沒有輸入專案 ID。"
if gcloud projects describe "$GCP_PROJECT" >/dev/null 2>&1; then
  say "找到既有專案 $GCP_PROJECT。"
else
  confirm "找不到 $GCP_PROJECT，要新建這個專案嗎？" || stop "已取消。"
  run gcloud projects create "$GCP_PROJECT" --name="AngKorGit zh-TW"
fi
write_env GCP_PROJECT "$GCP_PROJECT"
set_var GCP_PROJECT "$GCP_PROJECT"
pause

stage "計費帳戶"
say "Cloud Translation 要求專案已連結計費帳戶，使用會產生費用。"
note "定價請見 https://cloud.google.com/translate/pricing"
open_url "https://console.cloud.google.com/billing/linkedaccount?project=$GCP_PROJECT"
step "在開啟的頁面確認專案 $GCP_PROJECT 已連結計費帳戶；還沒有的話，依頁面指示連結一個。"
pause "連結好後按 Enter"
if [[ "$(gcloud billing projects describe "$GCP_PROJECT" --format='value(billingEnabled)' 2>/dev/null || true)" != "True" ]]; then
  warn "gcloud 回報這個專案尚未啟用計費。"
  confirm "仍要繼續嗎？（下一步啟用 API 可能會失敗）" || stop "已取消，連結計費帳戶後再重跑。"
fi

stage "啟用 API"
say "啟用 Cloud Translation 與 Cloud Storage。"
run gcloud services enable translate.googleapis.com storage.googleapis.com --project "$GCP_PROJECT"
pause

stage "上傳術語表到 Cloud Storage"
say "術語表資源必須從 Cloud Storage 的檔案建立，bucket 放在 $REGION。"
note "bucket 名稱全球唯一。直接按 Enter 會用 ${GCP_PROJECT}-termbase。"
ask GCS_BUCKET "bucket 名稱："
[[ -n "$GCS_BUCKET" ]] || GCS_BUCKET="${GCP_PROJECT}-termbase"
if gcloud storage buckets describe "gs://$GCS_BUCKET" --project "$GCP_PROJECT" >/dev/null 2>&1; then
  say "bucket gs://$GCS_BUCKET 已存在，直接使用。"
else
  run gcloud storage buckets create "gs://$GCS_BUCKET" --project "$GCP_PROJECT" --location "$REGION" --uniform-bucket-level-access
fi
run gcloud storage cp "$TERMBASE" "gs://$GCS_BUCKET/termbase.csv" --project "$GCP_PROJECT"
write_env GCS_BUCKET "$GCS_BUCKET"
set_var GCS_BUCKET "$GCS_BUCKET"
pause

stage "建立術語表"
note "直接按 Enter 會用 git-zh-tw。"
ask GLOSSARY_ID "術語表 ID："
[[ -n "$GLOSSARY_ID" ]] || GLOSSARY_ID="git-zh-tw"
TOKEN=$(gcloud auth print-access-token)
BUILD=1
if [[ "$(api GET "/glossaries/$GLOSSARY_ID")" == "200" ]]; then
  say "術語表 $GLOSSARY_ID 已存在，共 $(jq -r '.entryCount // "?"' "$TMP/out.json") 條。"
  if confirm "要用剛上傳的 termbase.csv 重建嗎？（會先刪除舊的）"; then
    code=$(api DELETE "/glossaries/$GLOSSARY_ID")
    [[ "$code" == 2* ]] || { cat "$TMP/out.json"; stop "刪除術語表失敗（HTTP $code）。"; }
    printf '  等待刪除完成'
    wait_for 404 "/glossaries/$GLOSSARY_ID" || stop "等待刪除逾時，稍後再重跑。"
  else
    BUILD=0
  fi
fi
if (( BUILD )); then
  jq -n --arg name "projects/$GCP_PROJECT/locations/$REGION/glossaries/$GLOSSARY_ID" --arg uri "gs://$GCS_BUCKET/termbase.csv" \
    '{name: $name, languagePair: {sourceLanguageCode: "en", targetLanguageCode: "zh-TW"}, inputConfig: {gcsSource: {inputUri: $uri}}}' \
    > "$TMP/glossary.json"
  code=$(api POST "/glossaries" -d "@$TMP/glossary.json")
  [[ "$code" == 2* ]] || { cat "$TMP/out.json"; stop "建立術語表失敗（HTTP $code）。"; }
  printf '  等待術語表建立完成'
  wait_for 200 "/glossaries/$GLOSSARY_ID" || stop "等待建立逾時；請到 Cloud Console 查看術語表的錯誤訊息後重跑。"
  say "術語表 $GLOSSARY_ID 已建立，共 $(jq -r '.entryCount // "?"' "$TMP/out.json") 條。"
fi
write_env GLOSSARY_ID "$GLOSSARY_ID"
set_var GLOSSARY_ID "$GLOSSARY_ID"
pause

stage "服務帳戶與金鑰"
SA_EMAIL="$SA_NAME@$GCP_PROJECT.iam.gserviceaccount.com"
say "GitHub Actions 會以服務帳戶 $SA_EMAIL 呼叫翻譯 API。"
if ! gcloud iam service-accounts describe "$SA_EMAIL" --project "$GCP_PROJECT" >/dev/null 2>&1; then
  run gcloud iam service-accounts create "$SA_NAME" --project "$GCP_PROJECT" --display-name "AngKorGit zh-TW translation"
fi
say "授予 Cloud Translation API User 角色。"
gcloud projects add-iam-policy-binding "$GCP_PROJECT" --member "serviceAccount:$SA_EMAIL" \
  --role roles/cloudtranslate.user --condition=None >/dev/null
HAVE_KEY=0
note "每次產生都是一把新金鑰，舊金鑰不會自動失效。要清理請到："
note "https://console.cloud.google.com/iam-admin/serviceaccounts?project=$GCP_PROJECT"
if confirm "要產生一把新金鑰並存成 GitHub secret GCP_SA_KEY 嗎？"; then
  run gcloud iam service-accounts keys create "$TMP/key.json" --iam-account "$SA_EMAIL" --project "$GCP_PROJECT"
  set_secret GCP_SA_KEY "$(cat "$TMP/key.json")"
  HAVE_KEY=1
else
  note "已略過。CI 需要 secret GCP_SA_KEY 才能翻譯。"
fi
pause

stage "驗證"
if (( HAVE_KEY )) && SA_TOKEN=$(GOOGLE_APPLICATION_CREDENTIALS="$TMP/key.json" gcloud auth application-default print-access-token 2>/dev/null); then
  TOKEN="$SA_TOKEN"
  say "用服務帳戶的金鑰實際翻譯兩句。"
else
  TOKEN=$(gcloud auth print-access-token)
  warn "改用你自己的帳號驗證；服務帳戶的權限要等 CI 第一次執行才會驗到。"
fi
jq -n --arg glossary "projects/$GCP_PROJECT/locations/$REGION/glossaries/$GLOSSARY_ID" \
  '{sourceLanguageCode: "en", targetLanguageCode: "zh-TW", mimeType: "text/plain", contents: ["Stash changes", "Rebase onto main"], glossaryConfig: {glossary: $glossary, ignoreCase: true}}' \
  > "$TMP/translate.json"
note "新授予的權限可能要等一兩分鐘才生效，會自動重試。"
VERIFIED=0
for _ in $(seq 1 12); do
  code=$(api POST ":translateText" -d "@$TMP/translate.json")
  if [[ "$code" == "200" ]]; then VERIFIED=1; break; fi
  printf '.'; sleep 10
done
printf '\n'
if (( VERIFIED )); then
  say "Stash changes / Rebase onto main 的翻譯結果："
  jq -r '.glossaryTranslations[]?.translatedText' "$TMP/out.json" | while IFS= read -r line; do step "$line"; done
  note "術語表有生效的話，應該會看到「貯存」與「重定基底」。"
else
  cat "$TMP/out.json"
  warn "翻譯請求失敗（HTTP $code），請依上面的錯誤訊息處理後重跑這支腳本。"
  SKIPPED+=("翻譯驗證未通過")
fi
rm -f "$TMP/key.json"
say "本機的金鑰檔已刪除，金鑰只存在 GitHub secret。"
pause

finish
}

run_wizard "$@"; exit
